        "code": "def main(url: str) -> dict:\n\t# Clean the URL\n\turl = url.rstrip('/')\n\tif url.endswith('.git'):\n\t\turl = url[:-4]\n\t\n\t# Extract owner and repo\n\t# Assuming format: https://github.com/owner/repo\n\tparts = url.split('/')\n\towner = parts[-2]\n\trepo = parts[-1]\n\t\n\t# Construct GitHub API URL for recursive tree\n\tapi_url = f\"https://api.github.com/repos/{owner}/{repo}/git/trees/HEAD?recursive=1\"\n\t\n\treturn {\"api_url\": api_url}"
