        "code": "import json\n\ndef main(body: str) -> dict:\n\ttry:\n\t\tdata = json.loads(body)\n\t\titems = data.get('tree', [])\n\texcept Exception as e:\n\t\treturn {\"file_structure\": f\"Error parsing API response: {str(e)}\"}\n\n\t# Sort items: Directories first, then files, alphabetically\n\titems.sort(key=lambda x: (x['type'] != 'tree', x['path']))\n\n\t# Build a map of parent -> children\n\tchildren = {}\n\tfor item in items:\n\t\tpath = item['path']\n\t\tparts = path.split('/')\n\t\tparent = '/'.join(parts[:-1]) # Parent path\n\t\t\n\t\tif parent not in children:\n\t\t\tchildren[parent] = []\n\t\tchildren[parent].append(item)\n\n\t# Recursive function to build the tree string\n\tdef build_tree(parent_path: str, prefix: str) -> str:\n\t\tif parent_path not in children:\n\t\t\treturn \"\"\n\t\t\n\t\tlines = []\n\t\tsiblings = children[parent_path]\n\t\t\n\t\tfor index, item in enumerate(siblings):\n\t\t\tis_last = (index == len(siblings) - 1)\n\t\t\t\n\t\t\t# Determine connector\n\t\t\tconnector = \"└── \" if is_last else \"├── \"\n\t\t\t\n\t\t\t# Get the name of the current item (last part of path)\n\t\t\tname = item['path'].split('/')[-1]\n\t\t\t\n\t\t\tlines.append(f\"{prefix}{connector}{name}\")\n\t\t\t\n\t\t\t# If it's a directory, process its children\n\t\t\tif item['type'] == 'tree':\n\t\t\t\t# Update prefix for the next level\n\t\t\t\t# If current is last, indent with spaces, else with pipe\n\t\t\t\tnew_prefix = prefix + (\"    \" if is_last else \"│   \")\n\t\t\t\tlines.append(build_tree(item['path'], new_prefix))\n\t\t\n\t\treturn \"\\n\".join(lines)\n\n\t# Start from root (empty string)\n\tresult = build_tree(\"\", \"\")\n\treturn {\"file_structure\": result}"
